from django.test import TestCase
from django.db import IntegrityError, transaction
from inventory.models import Product, Stock, Warehouse
from catalog.utils import convert_to_unit

class ProductModelTest(TestCase):
    def setUp(self):
        # *SKU should be autogenerated
        self.sku = "SKU-001"
        self.product = Product.objects.create(
            name="Rice",
            unit="kg",
            description="Premium rice",
        )
        
        #* Create a product, product is saved with the correct fields
    def test_create_product(self):
        """A product can be created with the expected fields."""
        self.assertEqual(self.product.sku, self.sku)
        self.assertEqual(self.product.name, "Rice")
        self.assertEqual(self.product.unit, "kg")
        self.assertEqual(self.product.description, "Premium rice")

        #* Default is_active
    def test_default_is_active(self):
        self.assertTrue(self.product.is_active)

    #* String representation "SKU-001 - Rice (kg)"
    def test_string_representation(self):
        self.assertEqual(
            str(self.product),
            "SKU-001 - Rice (kg)",
        )

    #* Duplicate SKU, Database rejects duplicate SKUs
    def test_sku_must_be_unique(self):
        with self.assertRaises(IntegrityError):
            with transaction.atomic():
                Product.objects.create(
                    sku=self.sku,
                    name="Another Rice",
                    unit="kg",
                )

    #* Creation timestamp, created_at is populated
    def test_created_at_is_populated(self):
        self.assertIsNotNone(self.product.created_at)

    #* No stock records, on_hand returns 0
    def test_on_hand_without_stock_returns_zero(self):
        self.assertEqual(self.product.on_hand, 0)
        
    #* Multiple stocks record, on_hand returns its quantity from multiple warehouses
    def test_on_hand_sums_multiple_stock_records(self):
        warehouse_jkt = Warehouse.objects.create(
            code="WH-1",
            name="Warehouse Jakarta-1",
            location="Jakarta"
        )
        warehouse_sby = Warehouse.objects.create(
            code="WH-2",
            name="Warehouse Surabaya-2",
            location="Surabaya"
        )
        Stock.objects.create(
            product=self.product,
            quantity=10,
            warehouse=warehouse_jkt
        )
        Stock.objects.create(
            product=self.product,
            quantity=25,
            warehouse=warehouse_sby
        )

        self.assertEqual(self.product.on_hand, 35)

class UnitConversionTestCase(TestCase):
    def test_convert_to_unit(self):
        # Test conversion from Each to Pack
        value_in_pack = convert_to_unit(12, Product.MeasurementUnit.EA, Product.MeasurementUnit.PK)
        self.assertEqual(value_in_pack, 2.0)

        # Test conversion from Pack to Each
        value_in_each = convert_to_unit(3, Product.MeasurementUnit.PK, Product.MeasurementUnit.EA)
        self.assertEqual(value_in_each, 18.0)

        # Test conversion from Each to Case
        value_in_case = convert_to_unit(36, Product.MeasurementUnit.EA, Product.MeasurementUnit.CS)
        self.assertEqual(value_in_case, 1.5)

        # Test conversion from Each to Pallet
        value_in_each_from_pallet = convert_to_unit(1200, Product.MeasurementUnit.EA, Product.MeasurementUnit.PLT)
        self.assertEqual(value_in_each_from_pallet, 1.0)